// Node-RED Function node
// Receives topics: bms/cellVoltage/1/0 ... bms/cellVoltage/1/15
// Each msg.payload is a voltage value

// Initialize context storage if not already
let minData = context.get("minData") || { cell: null, value: Number.POSITIVE_INFINITY };
let maxData = context.get("maxData") || { cell: null, value: Number.NEGATIVE_INFINITY };

let voltage = Number(msg.payload);
let topic = msg.topic;

// Extract cell number (last element of topic split by '/')
let parts = topic.split("/");
let cellNumber = parseInt(parts[parts.length - 1]);

// Update minimum
if (voltage < minData.value) {
    minData = { cell: cellNumber, value: voltage };
    context.set("minData", minData);
}

// Update maximum
if (voltage > maxData.value) {
    maxData = { cell: cellNumber, value: voltage };
    context.set("maxData", maxData);
}
if(cellNumber < 15){ 
    //don't update UI until we have received the 16th voltage score
    return;
}

//send the message and clear the min/max values

// Prepare output messages
let minMsg = { topic: "Cell " + minData.cell, payload: minData.value };
let maxMsg = { topic: "Cell " + maxData.cell, payload: maxData.value };
context.set("minData", { cell: null, value: Number.POSITIVE_INFINITY });
context.set("maxData", { cell: null, value: Number.NEGATIVE_INFINITY });
// Return as array of outputs: [min, max]
return [minMsg, maxMsg];

