// Cache the latest value of every HUD field, tagged with its arrival time.
const MAP = {
    "gps/speed/0":                     "sog",
    "gps/course/0":                    "cog",
    "imu/0/heading":                   "hdg",
    "anemometer/windSpeed/2":          "tws",
    "anemometer/windDirection/2":      "twd",
    "anemometer/windSpeed/1":          "aws",
    "anemometer/windDirection/0":      "awa",   // measured relative to the bow
    "anemometer/windDirection/1":      "awd",   // apparent wind as a compass bearing
    "sevCon/rpm0":                     "rpm",
    "sevCon/current0":                 "cur",
    "sevCon/temperature/controller/0": "ctrl",
    "sevCon/temperature/motor/0":      "mot"
};

const key = MAP[msg.topic];
if (!key) {
    return null;
}

const value = parseFloat(msg.payload);
if (!isFinite(value)) {
    return null;
}

const hud = flow.get("hud") || {};
hud[key] = { v: value, t: Date.now() };
flow.set("hud", hud);
return null;

// Build the JSON the phone polls for. Everything is a {v, age} pair so the
// page can dim a reading whose sensor has gone quiet.
const RPM_DEADBAND = 5;    // rpm this close to zero counts as stopped
const MOTOR_HOLD_S = 10;   // stay on the motor panels this long after it stops

function norm180(a) {
    return ((((a + 180) % 360) + 360) % 360) - 180;
}

const now = Date.now();
const hud = flow.get("hud") || {};
const get = k => (hud[k] && isFinite(hud[k].v)) ? hud[k] : null;

const hdg = get("hdg");
const twd = get("twd");

// TWA is not measured anywhere: it is the true wind direction seen from the bow
let twa = null;
if (twd && hdg) {
    twa = { v: norm180(twd.v - hdg.v), t: Math.min(twd.t, hdg.t) };
}

// AWA comes straight off the masthead unit (subnode 0, already bow relative).
// If that topic is not being published, derive it from the compass version.
let awa = get("awa");
if (awa) {
    awa = { v: norm180(awa.v), t: awa.t };
} else {
    const awd = get("awd");
    if (awd && hdg) {
        awa = { v: norm180(awd.v - hdg.v), t: Math.min(awd.t, hdg.t) };
    }
}

// Is the motor turning? The page swaps the wind panels for the SevCon readings
// while it is. Held for a few seconds so a lumpy idle cannot flip the panels
// back and forth, and treated as stopped if the SevCon has gone quiet.
const rpm = get("rpm");
if (rpm && Math.abs(rpm.v) > RPM_DEADBAND) {
    flow.set("hudMotorLast", rpm.t);   // arrival time, so a silent SevCon times out too
}
const motor = (now - (flow.get("hudMotorLast") || 0)) < MOTOR_HOLD_S * 1000;

const latest = {
    sog: get("sog"),
    cog: get("cog"),
    hdg: hdg,
    tws: get("tws"),
    twd: twd,
    aws: get("aws"),
    twa: twa,
    awa: awa,
    rpm: rpm,
    cur: get("cur"),
    ctrl: get("ctrl"),
    mot: get("mot")
};

const fields = {};
for (const k of Object.keys(latest)) {
    const f = latest[k];
    fields[k] = f ? { v: f.v, age: (now - f.t) / 1000 } : null;
}

msg.payload = { now: now, motor: motor, fields: fields };
return msg;

// Fake a plausible upwind reach so the HUD can be checked without the boat.
// Enable this inject node only for testing.
const s = context.get("s") || { t: 0 };
s.t += 1;
const wobble = Math.sin(s.t / 9);
context.set("s", s);

const hdg = 192 + wobble * 3;
const twd = 84 + wobble * 6;
const tws = 19.5 + wobble * 1.2;
const sog = 15.9 + wobble * 0.6;

return [[
    { topic: "gps/speed/0",                payload: sog },
    { topic: "gps/course/0",               payload: (hdg + 4 + 360) % 360 },
    { topic: "imu/0/heading",              payload: hdg },
    { topic: "anemometer/windSpeed/2",     payload: tws },
    { topic: "anemometer/windDirection/2", payload: (twd + 360) % 360 },
    { topic: "anemometer/windSpeed/1",     payload: tws + 6 },
    { topic: "anemometer/windDirection/0", payload: (304 + wobble * 4 + 360) % 360 }
]];

// Fake the SevCon running so the motor panels can be checked at the dock.
// Enable this inject node only for testing.
const s = context.get("s") || { t: 0 };
s.t += 1;
const wobble = Math.sin(s.t / 11);
context.set("s", s);

return [[
    { topic: "sevCon/rpm0",                     payload: 1450 + wobble * 120 },
    { topic: "sevCon/current0",                 payload: 62.4 + wobble * 8 },
    { topic: "sevCon/temperature/controller/0", payload: 41 + wobble * 2 },
    { topic: "sevCon/temperature/motor/0",      payload: 58 + wobble * 3 }
]];

var hws = flow.get("hws")||0;
var solar = flow.get("solar")||0;
var power = flow.get('power')||0;
var importing = flow.get('importing')||0;
var exporting = flow.get('exporting')||0;
var car = flow.get('car')||0;


var usage = parseInt(msg.payload);
var topic = msg.topic;
var n = topic.length
switch(topic.charAt(n-1))
{
    case "0": 
        hws = usage;
        flow.set("hws", usage);
        break;
    case "1": 
        //inverter set in Calculate solar production
        var schneiderInverter = usage;
        var inverter1 = flow.get("inverter/pvInputPower/0")||0
        var inverter2 = flow.get("inverter/pvInputPower/1")||0
        solar = schneiderInverter+inverter1+inverter2;
        flow.set("schneiderInverter",schneiderInverter);
        flow.set("solar", solar);

        //Calculate the exporting amount based on the average import value when there is no solar
        var averageImport = 0;
        var importCount = flow.get("importCount")||0;
        if(importCount != 0)
        {
            var importSum = flow.get("importSum")||0;
            averageImport = importSum/importCount; 
        }

        if( schneiderInverter > averageImport )
        {
            exporting = schneiderInverter - averageImport;
        }
        else
        {
            exporting = 0; 
        }
        flow.set("exporting", exporting);
        break;
    case "2": 
        power = usage;
        flow.set("power", usage);
        break;
    case "3":
        importing = usage;
        flow.set("importing", usage);
        if(importing > 0)
        {
            //update the values for average importing
            var importCount_ = flow.get("importCount")||0;
            var importSum_ = flow.get("importSum")||0;
            flow.set('importSum', importSum_ + importing);
            flow.set('importCount', importCount_ + 1);
        }
        break;
    case "4":
        car = usage;
        flow.set("car", usage);
        break;
    default:
        return;
}

msg.hws = hws;
msg.solar = solar;
msg.power =power;
msg.importing = importing;
msg.exporting = Math.round(exporting);
msg.payload = power;  //for trail plot
msg.car = car;


return msg;

msg.HWSTotal = flow.get("hwsTotal") || 0 + "wh";
msg.carTotal = flow.get("carTotal") || 0;
msg.importTotal = flow.get("importTotal") || 0;
msg.powerTotal = flow.get("powerTotal") || 0;
msg.exportTotal = Math.round(flow.get("exportTotal") || 0);
msg.solarTotal = Math.round(flow.get("solarTotal") || 0);
msg.importCost = "$" + (msg.importTotal /1000 *0.262).toFixed(2);
msg.HWSCost = "$" + ((flow.get("hwsTotal")||0) /1000 *0.262).toFixed(2);
msg.exportValue = "$" + ((flow.get("exportTotal") || 0) / 1000 * 0.07135).toFixed(2);
msg.exportValue = "$" + ((flow.get("exportTotal") || 0) / 1000 * 0.07135).toFixed(2);

var channel = msg.topic.charAt(msg.topic.length - 1);
msg.pulseChannel = "Pulse Channel "+ channel;

var dailyStart = flow.get('DayStartPulse'+channel )||0;
if( dailyStart === 0 )
{
    dailyStart = parseInt(msg.payload);
    flow.set('DayStartPulse'+channel,dailyStart);
}
var dailyUsage = parseInt(msg.payload) - dailyStart;
switch(channel)
{
    case "0": 
        flow.set("hwsTotal", dailyUsage);
        msg.HWSTotal = dailyUsage;
        break;
    case "1": 
        //the other two invertes pulse we calculate internally
        var inverter1 = flow.get('inverterDailyTotal:inverter/pvInputPower/0') || 0;
        var inverter2 = flow.get('inverterDailyTotal:inverter/pvInputPower/1') || 0;
        var totalProduction = dailyUsage+inverter1+inverter2;
        flow.set("solarTotal", totalProduction);
        msg.solarTotal = Math.round(totalProduction);
        break;
    case "2": 
        flow.set("powerTotal", dailyUsage);
        msg.powerTotal = dailyUsage;
        break;
    case "3": 
        flow.set("importTotal", dailyUsage);
        msg.importTotal = dailyUsage;
        break;
    case "4": 
        flow.set("carTotal", dailyUsage);
        msg.carTotal = dailyUsage;
        break;
    default:
        return;
}
return msg;

// Temperature node 0 contains 4 sensors
var on = parseInt(msg.payload);
var topic = msg.topic;
var n = topic.length
switch(msg.topic.charAt(n-1))
{
    case "0": 
        msg.topic = "Solar panel pump"; 
        msg.payload = (on?5:null);
        break;
    case "1": 
        msg.topic = "Internal pump";
        msg.payload = (on?4:null);
        break;
    case "2": 
        msg.topic = "Heat Pump"; 
        msg.paylaod = (on?3:null);
        break;
}

return msg;

var dailyStart = flow.get('DayStartCount')||0;
var flowCount = parseInt(msg.payload,10);
var lastFlowCount = flow.get("lastFlowCount")||0;
if( dailyStart === 0)  //reset in Main and bore water use midnight reset
{
    flow.set('DayStartCount',flowCount);
    flow.set("lastFlowCount",flowCount);
    flow.set("flowStartTime", 0);
    dailyStart = flowCount;
}

if( lastFlowCount != flowCount)  //water flowing
{
    if( flow.get("flowStartTime") === 0)    //start of a new water flow. Tap turned on.
    {
        flow.set("flowStartTime", new Date() );
        flow.set("flowStartCount", flowCount);
    }
}
else if( lastFlowCount == flowCount  && (flow.get("flowStartCount")||0) !== 0 )
{   
    //water has stopped flowing
    var flowTime = (new Date() - flow.get("flowStartTime"))/1000; //convert from ms to seconds
    flow.set("totalShowerTime", (flow.get("totalShowerTime")||0) + flowTime);
    if( flowTime > 180)   //only consider flow for longer than 3 minute as a shower!
        flow.set("totalShowers", (flow.get("totalShowers")||0) +1);
    flow.set("flowStartTime", 0);    //reset the trigger for neext start of HW flow
    flow.set("flowStartCount",0);
}
flow.set("lastFlowCount",flowCount);

msg.dailyStart = dailyStart;
msg.flowCount = flowCount;
msg.lastFlowCount = lastFlowCount;
msg.flowStartTime = flow.get("flowStartTime");
msg.flowStartCount = flow.get("flowStartCount");
msg.totalShowerSeconds = flow.get("totalShowerTime");

msg.totalShowers = flow.get("totalShowers")||0;
msg.totalWaterUsed =  Math.round(flowCount - dailyStart);
var showerTime  = (flow.get("totalShowerTime")||0); //convert from ms to seconds
if( showerTime < 60 )
    msg.totalShowerTime = Math.round(showerTime) + " sec"
else
    msg.totalShowerTime = Math.round(showerTime/60) + " min"

return msg;

var temperature = parseInt(msg.payload)
msg.hotWaterTemperature = temperature + "c";
if( temperature < 40 )
{
    msg.minutesRemaining = "Too cold";
    msg.payload = 0;
}   
else
{
    msg.minutesRemaining = Math.round((temperature-45)/0.7) + " min";    //temperature drops by 0.7c for each minute of shower
    msg.payload = Math.round((temperature-45)/0.7);
}
return msg;

var lastReading = context.get('lastScaleReading')||0;
var currentReading = parseInt(msg.payload);
context.set('lastScaleReading', currentReading );

var now = new Date();
var cocoLastFed = new Date(flow.get("cocoLastFed")||0);
var sendEmail = false;

if( lastReading - currentReading  >150)
{
    cocoLastFed = now;
    flow.set("cocoLastFed", cocoLastFed);
    sendEmail = true;
}

var monthDays = [ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 31, 31];

//msg.dogFoodRemaining = Math.round(parseInt(msg.payload)/100)/10 +" kg";
msg.dogFoodRemaining = Math.round(msg.payload/100)/10 +" kg";

if( cocoLastFed.getDate() === now.getDate() )
{
    msg.cocoLastFed = ["Today at ", cocoLastFed.toString().slice(16,21)].join("");
    msg.payload = 1;    //show green on level bar
}
else if( cocoLastFed.getDate() === now.getDate()-1 ||
         (now.getDate() === 1 && cocoLastFed.getDate() === monthDays[cocoLastFed.getMonth()-1]) )
{
    msg.cocoLastFed = ["Yesterday at ", cocoLastFed.toString().slice(16,21)].join("");
    msg.payload = 0;  //show red on level bar
}
else
{
    msg.cocoLastFed = "-";
    msg.payload = 2; //show grey on level bar
}


var endOfDayEmail;
endOfDayEmail = "<table>";
endOfDayEmail +=   "<tr><th>Coco last fed</th><td>"+ msg.cocoLastFed + "</td></tr>";
endOfDayEmail +=   "<tr><th>Dog food remaining</th><td>"+ msg.dogFoodRemaining + "</td></tr>";
endOfDayEmail += "</table>"
flow.set("DogFoodEndOfDayEmailMessage", endOfDayEmail);

//send an email now to let people know Coco has been fed
var emailMsg = null;
if( sendEmail )
{
    var tzoffset = (new Date()).getTimezoneOffset() * 60000; //offset in milliseconds
    var dateStr = (new Date(msg.payload - tzoffset - 86400000)).toISOString().substring(0,10).replace(/-/g,"");
    var payload =  "<a href='https://shannstainable.fewings.org/historic/&type=scale&date=" + dateStr+ "'>Dog food scale</a>"

    payload += "<table>";
    payload +=   "<tr><th>Amount fed</th><td>"+ (lastReading - currentReading).toString() + "g</td></tr>";
    payload +=   "<tr><th>Dog food remaining</th><td>"+ msg.dogFoodRemaining + "</td></tr>";
    payload += "</table>"

    emailMsg = {payload:payload, 
                topic: "Coco has just been fed"
    }
}


return [msg, emailMsg];

var dailyStart = flow.get('TankDayStartHeight')||0;
var tankHeight = parseInt(msg.payload,10);
var averageDailyUse = flow.get('TankAverageDailyUse') ||90;
if( dailyStart === 0)
{
    flow.set('TankDayStartHeight',tankHeight);
}

flow.set( "LastTankHeight", tankHeight);
const MIN_HEIGHT = 460;
msg.tankHeight = tankHeight + "mm";
if(tankHeight < MIN_HEIGHT )
{
    msg.payload = 0;
    msg.tankPercenet = "Empty";
    msg.tankDaysRemaining = 0;
}
else
{
    msg.tankPercent = Math.round( (tankHeight - MIN_HEIGHT)/(2050-MIN_HEIGHT) *100) + "%";
    msg.tankDaysRemaining = Math.round( (tankHeight - MIN_HEIGHT)/averageDailyUse);
    msg.payload = msg.tankPercent; //for level meter
}

var endOfDayEmail;
endOfDayEmail = "<table>";
