switch( YMDRange )
{
   case "Day":
        date = path.replace(/(\d\d\d\d)(\d\d)(\d\d)(.....)/g, '$2/$3/$1')
        var match = path.match(/(\d\d\d\d)(\d\d)(\d\d)(.....)/);
        chartTitle = match[3]+"-"+monthNames[Number(match[2])-1]+ "-"+match[1];
        break;
    case "Month":
        date = path.replace(/(\d\d\d\d)(\d\d)(.....)/g, '$2/01/$1')
        var match = path.match(/(\d\d\d\d)(\d\d)(.....)/);
        chartTitle = monthNames[Number(match[2])-1] + "-" + match[1];
        break;
    case "Year":
        date = path.replace(/(\d\d\d\d)(.....)/g, '01/01/$1')
        chartTitle = path.replace(/(\d\d\d\d)(.....)/g, '$1');
        break;
}
